-- MARKER_E032_APPLY basic-outland-world-levels
-- ============================================================================
-- 17-outland-world-levels.sql (issue 155k) — APPLY SOURCE
-- ============================================================================
-- Outland's open-world monsters are four levels higher (six on the Isle of
-- Quel'Danas). Ritz, 2026-09-24: "I think we might need to give all the
-- monsters in Outland a +4 level bonus, because a level 58 normal mob
-- dropping raid gear semi-rarely is... too powerful." / the Isle: "+6".
--
-- Raised: creature templates that
--   * stand only in Outland or on the Isle (map 530, y > -2000 or x > 11350;
--     a template also spawned anywhere else is left alone, so nothing in
--     Azeroth or Eversong moves);
--   * no player befriends (their faction template is in the generated list
--     below: hostile, or neutral like Nagrand's talbuks; a reputation
--     faction's people only if every race starts Hostile with it);
--   * are not townsfolk: a neutral one has no gossip, quest, vendor,
--     trainer or other service flag at all; a hostile one may talk or give a
--     quest (the Enraged Spirits, the Wyrmcult do) but has no service flag
--     past those two (the Netherwing Ledge's vendors are hostile Dragonmaw
--     until disguised, and stay stock);
--   * are not world bosses (rank 3; 155j: stock), critters, or invisible
--     spell triggers, and are not one of 155f's dungeon templates.
-- +6 when every spawn of the template is on the Isle, otherwise +4.
-- Not raised: creatures that only ever appear by being summoned (they have
-- no spawn to place them in Outland). Loot, health and damage tables are
-- untouched; health, damage and armor follow the new level as for any
-- creature of that level.
-- Stock levels saved (basic_155k_level_backup); each apply first restores
-- them, so re-applying is exact.
-- Database: acore_world_basic. Applied by E032, after E024 (155f), whose
-- template list it reads.
-- ============================================================================

-- ---- 0. put back what an earlier apply changed -------------------------------------
CREATE TABLE IF NOT EXISTS `basic_155k_level_backup` (
  `entry`    int unsigned     NOT NULL,
  `minlevel` tinyint unsigned NOT NULL,
  `maxlevel` tinyint unsigned NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='issue 155k: stock levels of the raised Outland world creatures, for the revert';
UPDATE `creature_template` t JOIN `basic_155k_level_backup` b ON b.`entry` = t.`entry`
SET t.`minlevel` = b.`minlevel`, t.`maxlevel` = b.`maxlevel`;
DELETE FROM `basic_155k_level_backup`;

