-- ---- 2. the raised templates and their step ----------------------------------------
DROP TABLE IF EXISTS `basic_155k_world_templates`;
CREATE TABLE `basic_155k_world_templates` (
  `entry`        int unsigned NOT NULL,
  `level_offset` tinyint      NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='issue 155k: raised Outland world templates and their step (read by scripts/validate-basic-state)';
INSERT INTO `basic_155k_world_templates` (`entry`, `level_offset`)
SELECT t.`entry`, IF(MIN(c.`position_x`) > 11350, 6, 4)
FROM `creature` c
JOIN `creature_template` t ON t.`entry` = c.`id`
JOIN `tmp_155k_factions` f ON f.`faction` = t.`faction`
WHERE t.`rank` <> 3 AND t.`type` <> 8 AND (t.`flags_extra` & 128) = 0
  AND IF(f.`kind` = 'n', t.`npcflag` = 0, (t.`npcflag` & ~3) = 0)     -- 1 gossip, 2 quest giver
  AND t.`entry` NOT IN (SELECT `entry` FROM `basic_155f_templates`)
GROUP BY t.`entry`
HAVING SUM(NOT (c.`map` = 530 AND (c.`position_y` > -2000 OR c.`position_x` > 11350))) = 0;

-- ---- 3. save, then raise -------------------------------------------------------------
INSERT INTO `basic_155k_level_backup` (`entry`, `minlevel`, `maxlevel`)
SELECT t.`entry`, t.`minlevel`, t.`maxlevel` FROM `creature_template` t JOIN `basic_155k_world_templates` w ON w.`entry` = t.`entry`;
UPDATE `creature_template` t JOIN `basic_155k_world_templates` w ON w.`entry` = t.`entry`
SET t.`minlevel` = t.`minlevel` + w.`level_offset`, t.`maxlevel` = t.`maxlevel` + w.`level_offset`;

DROP TABLE `tmp_155k_factions`;

